// Post-install landing for a NOT-signed-in visitor of /connect/installed.
//
// In practice that's the DESKTOP installer's SYSTEM browser: the install flow
// drops our CSRF state, so the broker routes the post-install redirect to the
// web app — but the user's token lives in the Electron app, not this tab. So
// we offer a `pyor://` deep link back into the app (handled by useDeepLink),
// plus a web sign-in fallback for the rare stray web visit.
//
// Signed-in web users never reach this component: the route's beforeLoad
// invalidates caches and redirects them straight to /pulls.

import { CheckCircle2 } from 'lucide-react';
import { useNavigate } from '@tanstack/react-router';
import { Button } from '@/components/ui/button';
import { PyorWindow } from '../../ui/PyorWindow';

export function InstalledLanding({ fluid = false }: { fluid?: boolean }) {
  const navigate = useNavigate();
  return (
    <PyorWindow
      title="Pyor"
      subtitle="Installation complete"
      fluid={fluid}
      hideStatusBar
      flushLeft
    >
      <div className="flex flex-1 flex-col items-center justify-center bg-panel px-8 py-10 text-center">
        <div className="inline-flex size-14 items-center justify-center rounded-2xl border bg-card shadow-sm">
          <CheckCircle2 className="size-6 text-pyor-pass" strokeWidth={1.8} />
        </div>
        <h1 className="mt-4 font-display text-[19px] font-semibold tracking-tight text-foreground">
          Repositories connected
        </h1>
        <p className="mx-auto mt-1.5 max-w-[440px] text-[13px] leading-relaxed text-muted-foreground">
          Pyor can now read the repositories you just selected. Return to the
          Pyor app to pick up where you left off.
        </p>
        <div className="mt-5 flex items-center gap-2.5">
          <Button
            className="gap-2"
            onClick={() => {
              window.location.href = 'pyor://installed';
            }}
          >
            Return to Pyor
          </Button>
        </div>
        <p className="mt-4 text-[11.5px] text-muted-foreground">
          You can close this tab. Not using the desktop app?{' '}
          <button
            type="button"
            onClick={() => void navigate({ to: '/welcome' })}
            className="text-primary hover:underline"
          >
            Sign in on the web
          </button>
          .
        </p>
      </div>
    </PyorWindow>
  );
}
